# Find all primes <= limit using a sieve, without a precomputed wheel.
fun sieve(limit: i64) -> List[i64] = {
    var primes: List[i64];
    if (limit < 2) return primes;

    var candidate: List[bool];
    var i: i64 = 0;
    while (i <= limit) {
        candidate.push(true);
        i = i + 1;
    }
    candidate.at(0) = false;
    candidate.at(1) = false;

    var p: i64 = 2;
    while (p <= limit / p) {
        if (candidate.at(p)) {
            var multiple = p * p;
            while (multiple <= limit) {
                candidate.at(multiple) = false;
                multiple = multiple + p;
            }
        }
        p = p + 1;
    }

    i = 2;
    while (i <= limit) {
        if (candidate.at(i)) primes.push(i);
        i = i + 1;
    }
    return primes;
}

