   for n := 2 to Round(Sqrt(limit)) do begin
      if not sieve[n] then begin
         for k := n*n to limit step n do
            sieve[k] := True;
      end;
   end;

   for k:=2 to limit do
      if not sieve[k] then
         Result.Add(k);
end;

