    | CIS(p, ptf) -> if p > lmt then List.rev lst |> List.map string_of_int
                                       |> String.concat "; "|> print_endline
                     else loop (p :: lst) (ptf())
  in loop [] pcis

let countprmsTo lmt pcis =
  let rec loop cnt = function
    | CIS(p, ptf) -> if p > lmt then cnt else loop (cnt + 1) (ptf())
  in loop 0 pcis

